"""Private financial research reader; exact decimal strings, no order actions."""
HTML=r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>财报研究 · 稻草财经</title><style>
:root{--bg:#f5f6f8;--panel:#fff;--ink:#182433;--muted:#718095;--line:#e4e9f0;--accent:#5264db;--soft:#eef1ff;--red:#bd4757;--green:#198273}*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--bg);font:14px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}a{color:var(--accent);text-decoration:none}button,input,select{font:inherit;color:inherit}button,input,select{border:1px solid var(--line);border-radius:8px;background:var(--panel);padding:9px 12px;min-width:0}button{cursor:pointer;touch-action:manipulation}button:disabled{opacity:.45;cursor:default}button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.primary{background:var(--accent);color:white;border-color:var(--accent)}header{background:var(--panel);border-bottom:1px solid var(--line);padding:14px 28px;display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}nav{display:flex;gap:18px;font-size:12px;align-items:center}.shell{max-width:1380px;margin:auto;padding:24px 28px 40px}.intro{display:flex;justify-content:space-between;gap:14px;align-items:center;margin-bottom:20px}h1{font-size:25px;letter-spacing:-.6px;margin:0}h2{font-size:18px;margin:0}h3{font-size:13px;margin:0}p{margin:4px 0}.muted,small{color:var(--muted);font-size:12px}.layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:18px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:20px;min-width:0}.sectionhead{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:14px}.badge{color:var(--accent);background:var(--soft);font-size:11px;padding:3px 8px;border-radius:6px}.list{display:grid;gap:9px}.record{text-align:left;width:100%;background:var(--bg);padding:13px}.record b,.record small{display:block;overflow-wrap:anywhere}.record[aria-current=true]{border-color:var(--accent);background:var(--soft)}.detail{display:grid;gap:16px;min-width:0}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.field{font-size:12px;color:var(--muted);display:flex;flex-direction:column;gap:5px}.field select,.field input{width:100%}#endpoints{grid-template-columns:1fr 1fr}.toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:15px}.check{display:flex;align-items:center;gap:7px}.check input{width:auto}.notice{border-radius:9px;padding:12px 14px;background:var(--soft);font-size:12px;overflow-wrap:anywhere}.error{background:#fff0f0;color:var(--red);margin-bottom:15px}.cards{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:16px 0}.metric{border:1px solid var(--line);border-radius:10px;padding:16px;min-width:0}.value{font-size:25px;font-weight:650;letter-spacing:-.6px;line-height:1.4;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}.loss{color:var(--red)}.component{padding:14px 0;border-top:1px solid var(--line)}.componenthead{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.componenthead b:last-child{text-align:right;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}.component p{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.digest{font-size:11px;font-family:ui-monospace,monospace;overflow-wrap:anywhere}details{margin-top:18px;color:var(--muted)}summary{cursor:pointer;font-size:12px}.controls{margin-top:12px;color:var(--ink)}.controls .grid{margin-top:12px}.controls summary{font-weight:600}.hidden{display:none!important}.empty{padding:28px 4px;color:var(--muted)}footer{font-size:11px;color:var(--muted);margin-top:22px}.listfoot{margin-top:12px;width:100%}@media(prefers-color-scheme:dark){:root{--bg:#10141c;--panel:#191f29;--ink:#e5eaf2;--muted:#98a4b6;--line:#2c3543;--accent:#a5afff;--soft:#252d47;--red:#f08090;--green:#6ac4b1}.primary{background:#5264db;color:white}.error{background:#34202a}}@media(max-width:1100px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){header{padding:12px 16px}nav{gap:12px}.shell{padding:18px 14px}.layout{grid-template-columns:1fr}.panel{padding:16px}.list{display:flex;overflow-x:auto;gap:10px}.record{min-width:205px;max-width:230px}.grid,.cards,#endpoints{grid-template-columns:1fr}.intro{align-items:flex-start}h1{font-size:23px}.value{font-size:24px}.componenthead{gap:8px}.componenthead b:last-child{max-width:60%}}
</style></head><body><header><a href="/"><b>稻草财经 / 研究</b></a><nav aria-label="研究导航"><a href="/api/quant-research/workspace">策略研究</a><a href="/api/quant-research/workspace?view=costs">账务核验</a><span aria-current="page">财报研究</span></nav></header><div class="shell"><div class="intro"><div><h1>财报时点研究</h1><p class="muted">同一提取版本与知识时点，核对利润、资产和原文依据。</p></div><button id="reload">刷新档案</button></div><div id="login" class="notice hidden">请先<a href="/">返回首页登录</a>，再查看所属研究档案。</div><div id="error" class="notice error hidden" role="alert"></div><div id="content" class="layout hidden"><aside class="panel"><div class="sectionhead"><h3>我的财报档案</h3><span class="badge">只读</span></div><div id="records" class="list"></div><button id="next" class="listfoot hidden">更多档案</button></aside><main class="detail"><section class="panel"><div id="metadata" class="empty">选择提取版本，核对同一时点的财务事实。</div><form id="queryform" class="hidden"><details id="controls" class="controls" open><summary>查询条件 · 证券、指标与知识时点</summary><div class="grid"><label class="field">证券<select id="security"></select></label><label class="field">流量报告期<select id="period"></select></label><label class="field">流量指标<select id="metric"></select></label><label class="field">知识模式<select id="mode"><option value="as_recorded">当时实存 · 同时检查两次入库</option><option value="historical_reconstruction">历史重建 · 使用晚采集资料</option></select></label><label class="field">知识时点 · 北京时间<input id="asof" type="datetime-local" step="1" required></label><label class="check"><input id="assets" type="checkbox">核对资产端点平均值</label></div><div id="endpoints" class="grid hidden" style="margin-top:12px"><label class="field">起点资产来源<select id="begin"></select></label><label class="field">终点资产来源<select id="end"></select></label></div></details><div class="toolbar"><button id="run" type="submit" class="primary">核对计算</button><span id="formhelp" class="muted"></span></div></form></section><section id="result" class="panel hidden" aria-live="polite"></section></main></div><footer>内部研究 · 原文为人工核对样本，完整会计可比性与时点数据尚未认证。算术可用不构成策略晋级依据。</footer></div><script>
'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const token=()=>{try{return localStorage.getItem('auth_token')||''}catch{return ''}};
const labels={consolidated_net_profit:'集团净利润',minority_net_profit:'少数股东损益',cashflow_asset_impairment:'资产减值准备',cashflow_inventory_decrease:'存货减少调节',cashflow_operating_receivable_decrease:'经营性应收减少',cashflow_operating_payable_increase:'经营性应付增加',cashflow_other:'其他现金流调节',cashflow_fixed_asset_depreciation:'固定资产折旧',cashflow_right_of_use_depreciation:'使用权资产折旧',cashflow_intangible_amortization:'无形资产摊销',cashflow_deferred_expense_amortization:'长期待摊费用摊销',cashflow_long_asset_disposal_loss:'长期资产处置损益调节',cashflow_scrapping_loss:'固定资产报废损益调节',cashflow_fair_value_loss:'公允价值变动调节',cashflow_finance_expense:'财务费用调节',cashflow_investment_loss:'投资损益调节',cashflow_deferred_tax_asset_decrease:'递延所得税资产减少',cashflow_deferred_tax_liability_increase:'递延所得税负债增加'};
const columns={current_period:'当前期末',previous_year_end:'上年度末',previous_year_end_adjusted:'上年度末 · 调整后'},roles={current_ytd:'本期累计流量',previous_annual:'上年全年流量',previous_comparable_ytd:'减去上年同期',current_annual:'本年全年流量',beginning_assets:'起点资产',ending_assets:'终点资产'};
const amount=v=>typeof v==='string'&&/^-?\d+(?:\.\d+)?$/.test(v)?v.replace(/\B(?=(\d{3})+(?!\d))/g,','):'—';
const bj=v=>{const d=new Date(v);return Number.isNaN(d.getTime())?'未知':d.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})};
const nowBJ=()=>new Date(Date.now()+8*3600000).toISOString().slice(0,19);
let owned=token(),generation=0,selection=0,queryVersion=0,items=[],cursor=null,active=null,metadata=null,loading=false,lastResult=null;
function error(v){$('error').textContent=v;$('error').classList.toggle('hidden',!v)}
function report(e){if(!e.stale)error(e.name==='AbortError'?'读取超时，请稍后刷新':e.message)}
function clearResult(){queryVersion++;lastResult=null;$('result').textContent='';$('result').classList.add('hidden');$('run').disabled=false}
function reset(){generation++;selection++;loading=false;items=[];cursor=null;active=null;metadata=null;clearResult();$('records').textContent='';$('metadata').textContent='';$('queryform').classList.add('hidden');$('content').classList.add('hidden');$('login').classList.toggle('hidden',!!token());$('next').classList.add('hidden');$('reload').disabled=false;error('')}
function session(g,t,s,q){if(g!==generation||t!==token()||s!=null&&s!==selection||q!=null&&q!==queryVersion){if(g===generation&&t!==token())reset();const e=Error('会话或选择已变化');e.stale=true;throw e}}
async function api(path,s=null,q=null){const t=token(),g=generation;if(!t)throw Error('请先返回首页登录');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);try{const r=await fetch('/api/quant-research'+path,{headers:{Authorization:'Bearer '+t},signal:controller.signal,cache:'no-store'});session(g,t,s,q);if(r.status===401){reset();$('login').classList.remove('hidden');throw Error('登录已过期，请重新登录')}if(!(r.headers.get('content-type')||'').includes('application/json'))throw Error('财报服务暂不可用，请稍后重试');const data=await r.json();session(g,t,s,q);if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'财报读取未完成');return data}finally{clearTimeout(timer)}}
function drawList(){$('records').innerHTML=items.map(r=>`<button class="record" data-record="${esc(r.id)}" aria-current="${r.id===active}"><b>${esc(r.label)}</b><small>提取 v${esc(r.revision)} · ${esc(r.fact_count)} 项事实</small><small>${esc(bj(r.recorded_at))}</small></button>`).join('')||'<p class="muted">暂无补充财报档案。由内部管理员核对原文后导入。</p>';$('next').classList.toggle('hidden',!cursor)}
async function load(more=false){if(loading)return;if(!token()){reset();return}const g=generation,startSelection=selection;loading=true;$('reload').disabled=true;error('');try{const data=await api('/financial-extractions'+(more&&cursor?'?cursor='+encodeURIComponent(cursor):''));if(g!==generation)return;items=more?[...new Map([...items,...data.items].map(x=>[x.id,x])).values()]:data.items;cursor=data.next_cursor;$('login').classList.add('hidden');$('content').classList.remove('hidden');drawList();if(!more&&startSelection===selection){selection++;metadata=null;active=null;clearResult();$('queryform').classList.add('hidden');$('metadata').textContent=items.length?'选择提取版本，核对同一时点的财务事实。':'暂无财报档案。';drawList()}}finally{if(g===generation){loading=false;$('reload').disabled=false}}}
function security(){return metadata?.securities[Number($('security').value)]}
function sourceOptions(s,target){return (s?.asset_sources||[]).filter(x=>x.point_date===target).map(x=>`<option value="${esc(x.report_period_end+'|'+x.column)}">${esc(x.report_period_end+' · '+(columns[x.column]||x.column))}</option>`).join('')}
function updateEndpoints(){const s=security(),end=$('period').value;const begin=end.endsWith('12-31')?(String(Number(end.slice(0,4))-1)+'-12-31'):(String(Number(end.slice(0,4))-1)+end.slice(4));$('begin').innerHTML=sourceOptions(s,begin)||'<option value="">缺少该日期资产</option>';$('end').innerHTML=sourceOptions(s,end)||'<option value="">缺少该日期资产</option>';$('endpoints').classList.toggle('hidden',!$('assets').checked);$('formhelp').textContent=$('assets').checked?'简单端点平均，保留半分钱；不是日均或季均资产。':'仅计算流量 TTM，不计算比率。'}
function setSecurity(){const s=security();$('period').innerHTML=(s?.report_periods||[]).map(p=>`<option>${esc(p)}</option>`).join('');$('metric').innerHTML=(s?.flow_metrics||[]).map(m=>`<option value="${esc(m)}">${esc(labels[m]||m)}</option>`).join('');if(s?.flow_metrics.includes('consolidated_net_profit'))$('metric').value='consolidated_net_profit';$('assets').checked=!!s?.asset_sources.length;$('assets').disabled=!s?.asset_sources.length;$('run').disabled=!s?.flow_metrics.length;updateEndpoints()}
async function selectPacket(id){const s=++selection;active=id;metadata=null;clearResult();drawList();$('metadata').textContent='正在核对提取链与原文指纹…';$('queryform').classList.add('hidden');const r=await api('/financial-extractions/'+encodeURIComponent(id),s);if(s!==selection)return;metadata=r;$('controls').open=true;$('metadata').classList.remove('empty');$('metadata').innerHTML=`<div class="sectionhead"><h2>${esc(r.label)}</h2><span class="badge">提取 v${esc(r.revision)}</span></div><p class="muted">入库 ${esc(bj(r.recorded_at))} · 当时实存可见 ${esc(bj(r.stored_visible_at))}</p>`;$('security').innerHTML=r.securities.map((x,i)=>`<option value="${i}">${esc(x.symbol)}</option>`).join('');$('asof').value=nowBJ();$('mode').value='as_recorded';$('queryform').classList.remove('hidden');setSecurity()}
function component(n){const f=n.fact,d=n.selected_document;return `<article class="component"><div class="componenthead"><b>${esc(roles[n.role]||n.role)}</b><b>${amount(f?.value)}</b></div><p>${esc(f?.period_start?f.period_start+' 至 '+f.period_end:f?.period_end||n.report_period_end)} · ${esc(d?'公告 '+d.document_id+' · 第 '+(f?.source_page||'—')+' 页':'未找到可见公告')}</p>${!f||f.value==null?'<p>缺少该版事实或披露空白，未补零或回退旧版。</p>':''}</article>`}
function render(r){lastResult=r;const ok=r.status==='arithmetic_available',gate=r.availability_reason==='receipt_not_yet_visible';let html=`<div class="sectionhead"><h2>${ok?'算术已核对':gate?'尚未到实存可见时点':'所需资料尚不完整'}</h2><button id="download" ${ok?'':'disabled'}>下载核验摘要</button></div><p class="muted">${r.request.mode==='historical_reconstruction'?'已见历史重建':'当时实存模式'} · 知识时点 ${esc(bj(r.request.as_of))}</p>`;
if(gate)html+=`<div class="notice">此次提取最早于 ${esc(bj(r.receipt.stored_visible_at))} 可用于实存查询。未展示财务部件或派生值。</div>`;
else{html+=`<div class="cards"><div class="metric"><small>${esc(labels[r.request.metric]||r.request.metric)} TTM · 元</small><div class="value ${r.ttm_value?.startsWith('-')?'loss':''}">${amount(r.ttm_value)}</div><p class="muted">${esc(r.period_start)} 至 ${esc(r.period_end)}</p></div><div class="metric"><small>端点平均资产 · 元</small><div class="value">${amount(r.endpoint_average_assets?.value_exact_yuan)}</div><p class="muted">${r.request.asset_endpoints?'两端简单平均 · 未按分取整':'本次未请求资产端点'}</p></div></div>`;if(!ok)html+='<div class="notice">缺失、空白或撤回的部件保持不可用，本次不输出部分派生值。</div>';for(const n of [...(r.result?.flow_components||[]),...(r.result?.asset_components||[])])html+=component(n)}
html+=`<details><summary>提取版本与审计依据</summary><p class="digest">${esc(r.receipt.fingerprint)}</p><p class="muted">同一提取快照、同一知识时点；原文为人工核对样本，未认证完整PIT或会计可比性。</p>${r.endpoint_average_assets?'<p class="digest">精确均值：'+esc(r.endpoint_average_assets.fraction_yuan.numerator)+' / '+esc(r.endpoint_average_assets.fraction_yuan.denominator)+' 元</p>':''}</details>`;$('result').innerHTML=html;$('result').classList.remove('hidden');$('controls').open=false;if(window.innerWidth<=760)$('result').scrollIntoView({behavior:'auto',block:'start'})}
async function runQuery(){if(!metadata)throw Error('请先选择财报档案');const s=selection;clearResult();const q=queryVersion;error('');const sec=security();if(!sec||!$('metric').value)throw Error('此版本没有可派生的流量指标');const params=new URLSearchParams({issuer_id:sec.issuer_id,symbol:sec.symbol,period_end:$('period').value,metric:$('metric').value,as_of:$('asof').value+'+08:00',mode:$('mode').value});if($('assets').checked){for(const [side,id] of [['begin','begin'],['end','end']]){const parts=$(id).value.split('|');if(parts.length!==2)throw Error('此提取版本缺少所需日期的资产，请改为仅查TTM或补齐档案');params.set(side+'_report_period_end',parts[0]);params.set(side+'_column',parts[1])}}$('run').disabled=true;try{const r=await api('/financial-extractions/'+encodeURIComponent(active)+'/derive?'+params.toString(),s,q);render(r)}finally{if(s===selection&&q===queryVersion)$('run').disabled=false}}
function download(){if(!lastResult||lastResult.status!=='arithmetic_available')return;const url=URL.createObjectURL(new Blob([JSON.stringify(lastResult,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='financial-research.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('reload').addEventListener('click',()=>{selection++;clearResult();load().catch(report)});$('next').addEventListener('click',()=>load(true).catch(report));$('queryform').addEventListener('submit',e=>{e.preventDefault();runQuery().catch(report)});$('security').addEventListener('change',()=>{clearResult();setSecurity()});$('period').addEventListener('change',()=>{clearResult();updateEndpoints()});$('assets').addEventListener('change',()=>{clearResult();updateEndpoints()});$('asof').addEventListener('input',clearResult);for(const id of ['metric','mode','asof','begin','end'])$(id).addEventListener('change',clearResult);
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.record)selectPacket(b.dataset.record).catch(report);if(b?.id==='download')download()});window.addEventListener('storage',()=>{if(token()!==owned){owned=token();reset();load().catch(report)}});window.addEventListener('pagehide',reset);window.addEventListener('pageshow',e=>{if(e.persisted){owned=token();reset();load().catch(report)}});load().catch(report);
</script></body></html>'''
